V3_CODE = '#!/usr/bin/env python3\n"""\nChatGPT Hotfix V3 for Brain V11\n- final execution guard: prevents MAX_POSITIONS overflow (6/5), duplicates, same-direction/sector overflow at the last moment before order submit\n- marks held symbols as blocked in candidate payload/UI\n- fixes Dashboard active function overrides (inserted before serve_forever) for equity/overmax/candidate clarity\n- enforces offline backtest no API fallback and adds filter-chain diagnostics\n- updates .demo.env and run_bt_fixed*.sh safely\n\nRun in /root/brain. It backs up modified files with timestamp.\n"""\nfrom __future__ import annotations\nimport os, re, shutil, textwrap, datetime\nfrom pathlib import Path\n\nROOT = Path(os.environ.get("BRAIN_ROOT", "/root/brain")).resolve()\nTS = datetime.datetime.utcnow().strftime("%Y%m%d_%H%M%S")\n\n\ndef backup(path: Path) -> None:\n    if path.exists():\n        shutil.copy2(path, path.with_suffix(path.suffix + f".bak_hotfix_v3_{TS}"))\n\n\ndef replace_block(text: str, start: str, end: str, block: str, insert_before: str) -> str:\n    pat = re.compile(re.escape(start) + r".*?" + re.escape(end) + r"\\n?", re.S)\n    text = pat.sub("", text)\n    idx = text.rfind(insert_before)\n    if idx < 0:\n        raise SystemExit(f"Cannot find insert marker: {insert_before!r}")\n    return text[:idx] + block.rstrip() + "\\n\\n" + text[idx:]\n\n\ndef upsert_env(env_path: Path, values: dict[str, str]) -> None:\n    lines = env_path.read_text(encoding="utf-8", errors="ignore").splitlines() if env_path.exists() else []\n    # remove duplicates for target keys, preserve comments and other lines\n    target = set(values)\n    new = []\n    for line in lines:\n        s = line.strip()\n        m = re.match(r"(?:export\\s+)?([A-Za-z_][A-Za-z0-9_]*)=", s)\n        if m and m.group(1) in target:\n            continue\n        new.append(line)\n    new.append("")\n    new.append("# === ChatGPT Hotfix V3 guard/UI/backtest ===")\n    for k, v in values.items():\n        new.append(f"export {k}={v}")\n    env_path.write_text("\\n".join(new).rstrip()+"\\n", encoding="utf-8")\n\n\nBRAIN_V3_BLOCK = r\'\'\'\n# === CHATGPT_HOTFIX_V3_START ===\n# Hotfix V3: final order guard, duplicate/over-max prevention, held-symbol candidate blocking,\n# offline backtest diagnostics, and stronger health snapshots. Inserted by ChatGPT.\ntry:\n    import json as _v3_json, time as _v3_time, logging as _v3_logging\n    from pathlib import Path as _v3_Path\nexcept Exception:\n    pass\n\n\ndef _v3_int(name, default=0):\n    try:\n        return int(float(os.environ.get(name, default)))\n    except Exception:\n        return int(default)\n\n\ndef _v3_float(name, default=0.0):\n    try:\n        return float(os.environ.get(name, default))\n    except Exception:\n        return float(default)\n\n\ndef _v3_bool(name, default=False):\n    return str(os.environ.get(name, "1" if default else "0")).strip().lower() in {"1","true","yes","y","on"}\n\n\ndef _v3_direction(pos):\n    try:\n        d = str((pos or {}).get("direction", "")).upper()\n        if d in {"LONG", "SHORT"}:\n            return d\n        amt = safe_float((pos or {}).get("positionAmt"), 0.0)\n        return "LONG" if amt > 0 else "SHORT" if amt < 0 else "UNKNOWN"\n    except Exception:\n        return "UNKNOWN"\n\n\ndef _v3_sector(symbol: str) -> str:\n    base = str(symbol).replace("USDT", "")\n    if base in {"BTC", "ETH", "BNB", "SOL", "XRP", "DOGE", "ADA", "AVAX", "LINK", "DOT"}:\n        return "LARGE_CAP"\n    if base in {"OP", "ARB", "STRK", "MANTA", "METIS"}:\n        return "L2"\n    if base in {"UNI", "AAVE", "CRV", "COMP", "MKR", "SUSHI", "PENDLE"}:\n        return "DEFI"\n    if base in {"PEPE", "WIF", "BONK", "SHIB", "FLOKI", "PENGU"}:\n        return "MEME"\n    if base in {"RNDR", "FET", "TAO", "AI", "AGIX", "WLD", "AIOT"}:\n        return "AI"\n    return "ALT"\n\n\ndef _v3_open_orders_for(client, symbol=None):\n    try:\n        if hasattr(client, "open_orders_all"):\n            return client.open_orders_all(symbol)\n        return client.open_orders(symbol)\n    except Exception:\n        return []\n\n\ndef _v3_position_counts(positions):\n    out = {"total": 0, "LONG": 0, "SHORT": 0, "UNKNOWN": 0, "sector": {}}\n    try:\n        out["total"] = len(positions or {})\n        for sym, pos in (positions or {}).items():\n            d = _v3_direction(pos)\n            out[d] = out.get(d, 0) + 1\n            sec = _v3_sector(str(sym))\n            out["sector"][sec] = out["sector"].get(sec, 0) + 1\n    except Exception:\n        pass\n    return out\n\n\ndef _v3_guard_reason_for_plan(broker, plan, pending_new_entries=0):\n    """Final exchange-level gate. Must be called immediately before any order request."""\n    try:\n        positions = broker.positions()\n    except Exception as exc:\n        return f"FINAL_GUARD_POSITIONS_READ_FAILED {exc}"\n    max_pos = _v3_int("MAX_POSITIONS", getattr(getattr(broker, "settings", None), "max_positions", 1))\n    counts = _v3_position_counts(positions)\n    total = counts.get("total", len(positions or {}))\n    sym = str(getattr(plan, "symbol", ""))\n    direction = str(getattr(plan, "direction", "")).upper()\n\n    if total >= max_pos:\n        return f"MAX_POSITIONS_FINAL_GUARD {total}/{max_pos}，冻结新增开仓"\n    if total + int(pending_new_entries or 0) >= max_pos:\n        return f"MAX_POSITIONS_PENDING_GUARD current={total} pending={pending_new_entries} max={max_pos}"\n    if sym in (positions or {}):\n        return f"DUPLICATE_POSITION_FINAL_GUARD {sym} 已有真实持仓"\n\n    orders = _v3_open_orders_for(getattr(broker, "client", None), sym)\n    # For a symbol with no position, any open order is treated as pending/duplicate.\n    if orders:\n        return f"DUPLICATE_ORDER_FINAL_GUARD {sym} open_orders={len(orders)}"\n\n    if direction == "LONG":\n        max_long = _v3_int("MAX_LONG_POSITIONS", _v3_int("MAX_SAME_DIRECTION_POSITIONS", max_pos))\n        if counts.get("LONG", 0) >= max_long:\n            return f"MAX_LONG_FINAL_GUARD {counts.get(\'LONG\',0)}/{max_long}"\n    elif direction == "SHORT":\n        max_short = _v3_int("MAX_SHORT_POSITIONS", _v3_int("MAX_SAME_DIRECTION_POSITIONS", max_pos))\n        if counts.get("SHORT", 0) >= max_short:\n            return f"MAX_SHORT_FINAL_GUARD {counts.get(\'SHORT\',0)}/{max_short}"\n\n    sec = _v3_sector(sym)\n    max_sector = _v3_int("MAX_POSITIONS_PER_SECTOR", _v3_int("MAX_SECTOR_POSITIONS", _v3_int("MAX_SAME_SECTOR_POSITIONS", max_pos)))\n    if counts.get("sector", {}).get(sec, 0) >= max_sector:\n        return f"MAX_SECTOR_FINAL_GUARD {sec} {counts.get(\'sector\',{}).get(sec,0)}/{max_sector}"\n    return ""\n\n\ndef _v3_patch_exchange_broker_final_guard():\n    B = globals().get("ExchangeBrokerV6") or globals().get("ExchangeBroker")\n    if not B or getattr(B, "_chatgpt_v3_final_guard", False):\n        return\n    prev_open = getattr(B, "open_position", None)\n    if not prev_open:\n        return\n\n    def open_position(self, plan, signal):\n        reason = _v3_guard_reason_for_plan(self, plan, pending_new_entries=0)\n        if reason:\n            _v3_logging.warning("%s symbol=%s direction=%s", reason, getattr(plan, "symbol", ""), getattr(plan, "direction", ""))\n            raise RuntimeError(reason)\n        return prev_open(self, plan, signal)\n\n    B.open_position = open_position\n    B._chatgpt_v3_final_guard = True\n\n\ndef _v3_patch_broker_can_open_today():\n    B = globals().get("ExchangeBrokerV6") or globals().get("ExchangeBroker")\n    if not B or getattr(B, "_chatgpt_v3_can_open_guard", False):\n        return\n    prev = getattr(B, "can_open_today", None)\n    if not prev:\n        return\n\n    def can_open_today(self, mark_prices):\n        ok, reason = prev(self, mark_prices)\n        if not ok:\n            return ok, reason\n        try:\n            positions = self.positions()\n            max_pos = _v3_int("MAX_POSITIONS", getattr(self.settings, "max_positions", 1))\n            if len(positions) >= max_pos:\n                return False, f"最大持仓硬闸门：当前 {len(positions)}/{max_pos}，冻结新增开仓"\n        except Exception as exc:\n            return False, f"最终持仓闸门读取失败：{exc}"\n        return True, reason\n\n    B.can_open_today = can_open_today\n    B._chatgpt_v3_can_open_guard = True\n\n\ndef _v3_patch_portfolio_risk():\n    P = globals().get("PortfolioRiskEngine")\n    if not P or getattr(P, "_chatgpt_v3_portfolio", False):\n        return\n    prev = getattr(P, "candidate_blockers", None)\n    if not prev:\n        return\n\n    def candidate_blockers(self, row, open_positions):\n        blockers = list(prev(self, row, open_positions) or [])\n        sym = str((row or {}).get("symbol", ""))\n        direction = str((row or {}).get("direction", "")).upper()\n        if sym and isinstance(open_positions, dict) and sym in open_positions:\n            blockers.append("已有真实持仓，禁止重复开仓")\n        max_pos = _v3_int("MAX_POSITIONS", getattr(getattr(self, "settings", None), "max_positions", 1))\n        counts = _v3_position_counts(open_positions or {})\n        if counts.get("total", 0) >= max_pos:\n            blockers.append(f"最大持仓达到上限 {counts.get(\'total\',0)}/{max_pos}")\n        if direction == "LONG" and counts.get("LONG", 0) >= _v3_int("MAX_LONG_POSITIONS", _v3_int("MAX_SAME_DIRECTION_POSITIONS", max_pos)):\n            blockers.append("LONG 持仓达到上限")\n        if direction == "SHORT" and counts.get("SHORT", 0) >= _v3_int("MAX_SHORT_POSITIONS", _v3_int("MAX_SAME_DIRECTION_POSITIONS", max_pos)):\n            blockers.append("SHORT 持仓达到上限")\n        sec = _v3_sector(sym)\n        sec_max = _v3_int("MAX_POSITIONS_PER_SECTOR", _v3_int("MAX_SECTOR_POSITIONS", _v3_int("MAX_SAME_SECTOR_POSITIONS", max_pos)))\n        if counts.get("sector", {}).get(sec, 0) >= sec_max:\n            blockers.append(f"同板块 {sec} 持仓达到上限 {counts.get(\'sector\',{}).get(sec,0)}/{sec_max}")\n        return list(dict.fromkeys([str(x) for x in blockers if str(x).strip()]))\n\n    P.candidate_blockers = candidate_blockers\n    P._chatgpt_v3_portfolio = True\n\n\ndef _v3_patch_process_dashboard_and_payload():\n    # Mark held symbols/max-position in payload before process_dashboard is written and before AI decides.\n    C = globals().get("BrainV8")\n    if not C or getattr(C, "_chatgpt_v3_payload_block", False):\n        return\n    prev = getattr(C, "build_ai_payload", None)\n    if not prev:\n        return\n\n    def build_ai_payload(self, regime, signals, marks):\n        payload = prev(self, regime, signals, marks)\n        try:\n            positions = self.broker.positions()\n            held = set((positions or {}).keys())\n            max_pos = _v3_int("MAX_POSITIONS", getattr(self.settings, "max_positions", 1))\n            over_or_full = len(held) >= max_pos\n            counts = _v3_position_counts(positions)\n            for row in payload.get("candidates", []) or []:\n                if not isinstance(row, dict):\n                    continue\n                sym = str(row.get("symbol", ""))\n                rbs = row.setdefault("risk_blockers", [])\n                if sym in held:\n                    row["risk_approved"] = False\n                    row["execution_blocked"] = True\n                    row["execution_block_reason"] = "已有真实持仓，禁止重复开仓"\n                    rbs.append("已有真实持仓，禁止重复开仓")\n                if over_or_full:\n                    row["risk_approved"] = False\n                    row["execution_blocked"] = True\n                    row["execution_block_reason"] = f"最大持仓达到上限 {len(held)}/{max_pos}"\n                    rbs.append(f"最大持仓达到上限 {len(held)}/{max_pos}")\n                row["risk_blockers"] = list(dict.fromkeys([str(x) for x in rbs if str(x).strip()]))\n            payload.setdefault("portfolio", {})["final_guard"] = {\n                "positions": len(held),\n                "max_positions": max_pos,\n                "over_max_positions": len(held) > max_pos,\n                "new_entries_frozen": len(held) >= max_pos,\n                "by_direction": {"LONG": counts.get("LONG",0), "SHORT": counts.get("SHORT",0)},\n                "by_sector": counts.get("sector", {}),\n            }\n            # Re-write the process dashboard after mutation if possible.\n            try:\n                self._write_process_dashboard(payload)\n            except Exception:\n                pass\n        except Exception:\n            _v3_logging.exception("CHATGPT_V3_PAYLOAD_BLOCK_FAILED")\n        return payload\n\n    C.build_ai_payload = build_ai_payload\n    C._chatgpt_v3_payload_block = True\n\n\ndef _v3_patch_health_monitor():\n    H = globals().get("HealthMonitor")\n    if not H or getattr(H, "_chatgpt_v3_health", False):\n        return\n    prev = getattr(H, "snapshot", None)\n    if not prev:\n        return\n\n    def snapshot(self, include_api=True):\n        obj = prev(self, include_api)\n        try:\n            cfg = obj.setdefault("config", {})\n            broker = obj.setdefault("broker", {})\n            positions = broker.get("position_detail") or {}\n            max_pos = _v3_int("MAX_POSITIONS", getattr(self.settings, "max_positions", 1))\n            counts = _v3_position_counts(positions)\n            cfg.update({\n                "MAX_POSITIONS": max_pos,\n                "MAX_NEW_ENTRIES_PER_CYCLE": _v3_int("MAX_NEW_ENTRIES_PER_CYCLE", getattr(self.settings, "max_new_entries_per_cycle", 1)),\n                "MAX_SAME_DIRECTION_POSITIONS": _v3_int("MAX_SAME_DIRECTION_POSITIONS", max_pos),\n                "MAX_LONG_POSITIONS": _v3_int("MAX_LONG_POSITIONS", max_pos),\n                "MAX_SHORT_POSITIONS": _v3_int("MAX_SHORT_POSITIONS", max_pos),\n                "MAX_SECTOR_POSITIONS": _v3_int("MAX_SECTOR_POSITIONS", max_pos),\n                "MAX_ALT_POSITIONS": _v3_int("MAX_ALT_POSITIONS", max_pos),\n                "MAX_POSITIONS_PER_SECTOR": _v3_int("MAX_POSITIONS_PER_SECTOR", max_pos),\n            })\n            broker["position_counts"] = counts\n            broker["over_max_positions"] = counts.get("total", 0) > max_pos\n            broker["new_entries_frozen"] = counts.get("total", 0) >= max_pos\n            if broker["over_max_positions"]:\n                obj.setdefault("blockers", []).append(f"OVER_MAX_POSITIONS {counts.get(\'total\',0)}/{max_pos}: 新开仓已冻结")\n                obj["status"] = "BLOCKED"\n            # enforce clear equity naming: equity = wallet + unreal when available\n            wallet = safe_float(broker.get("wallet_balance"), 0.0)\n            unreal = safe_float(broker.get("total_unrealized_pnl"), 0.0)\n            if wallet or unreal:\n                broker["equity"] = wallet + unreal\n                broker["margin_balance"] = wallet + unreal\n            _atomic_write_json(self.path, obj)\n        except Exception:\n            _v3_logging.exception("CHATGPT_V3_HEALTH_PATCH_FAILED")\n        return obj\n\n    H.snapshot = snapshot\n    H._chatgpt_v3_health = True\n\n\ndef _v3_patch_backtest_offline_and_diag():\n    C = globals().get("BinanceFuturesClientV9")\n    if C and not getattr(C, "_chatgpt_v3_offline", False):\n        prev_hist = getattr(C, "historical_klines", None)\n        def historical_klines(self, symbol, interval, start_ms, end_ms, limit):\n            offline = _v3_bool("BACKTEST_OFFLINE_ONLY", _v3_bool("NO_API_FALLBACK", False))\n            if offline:\n                raw_dir = env_str("LOCAL_KLINE_DIR", env_str("BINANCE_HISTORY_DIR", ""))\n                local_dir = _v3_Path(raw_dir).expanduser() if raw_dir else getattr(self, "local_kline_dir", None)\n                if local_dir:\n                    local = load_local_klines(local_dir, symbol, interval, start_ms, end_ms, max(1, int(limit)))\n                    if local:\n                        return local\n                _v3_logging.warning("BACKTEST_OFFLINE_ONLY_NO_LOCAL_DATA symbol=%s interval=%s start=%s end=%s", symbol, interval, start_ms, end_ms)\n                return []\n            return prev_hist(self, symbol, interval, start_ms, end_ms, limit)\n        if prev_hist:\n            C.historical_klines = historical_klines\n            C._chatgpt_v3_offline = True\n\n    B = globals().get("Backtester")\n    if not B or getattr(B, "_chatgpt_v3_diag", False):\n        return\n    prev_many = getattr(B, "backtest_many", None)\n    prev_sym = getattr(B, "backtest_symbol", None)\n    if not prev_many or not prev_sym:\n        return\n\n    def backtest_symbol(self, symbol, quote_volume=0.0, settings_override=None):\n        st = settings_override or self.settings\n        diag = {\n            "symbol": symbol, "raw_market_bars": 0, "raw_setups_total": 0,\n            "after_setup_whitelist": 0, "after_trend_disabled": 0, "after_breakout_disabled": 0,\n            "after_min_atr": 0, "after_score_threshold": 0, "after_confirm_v2": 0,\n            "after_cost_filter": 0, "after_rr_filter": 0, "final_trades": 0,\n            "reject_reasons": {}, "setup_counts": {},\n        }\n        try:\n            engine_cls = globals().get("StrategyEngineV10", globals().get("StrategyEngineV9", StrategyEngine))\n            engine = engine_cls(st, client=None)\n            start_ms = iso_to_ms(st.backtest_start) if st.backtest_start else None\n            end_ms = iso_to_ms(st.backtest_end) if st.backtest_end else None\n            entry = self.client.historical_klines(symbol, st.entry_interval, start_ms, end_ms, st.backtest_limit)\n            trend = self.client.historical_klines(symbol, st.trend_interval, start_ms, end_ms, max(500, st.backtest_limit // 4 + 300))\n            btc4 = self.client.historical_klines("BTCUSDT", st.regime_interval, start_ms, end_ms, max(500, st.backtest_limit // 16 + 300))\n            btc1 = self.client.historical_klines("BTCUSDT", st.trend_interval, start_ms, end_ms, max(500, st.backtest_limit // 4 + 300))\n            diag["raw_market_bars"] = len(entry)\n            if len(entry) < 250 or len(trend) < 150:\n                diag["reject_reasons"]["INSUFFICIENT_LOCAL_DATA"] = 1\n                getattr(self, "_v3_diag", {})[symbol] = diag\n                return []\n            allowed_setups = set(parse_csv_symbols(env_str("SETUP_WHITELIST", env_str("V11_SETUP_WHITELIST", "pullback"))))\n            trades = []\n            open_until = -1\n            for i in range(220, len(entry) - 2 - max(0, st.entry_delay_bars)):\n                if i <= open_until:\n                    continue\n                now_t = entry[i].close_time\n                trend_slice = slice_until_close(trend, now_t)\n                btc4_slice = slice_until_close(btc4, now_t)\n                btc1_slice = slice_until_close(btc1, now_t)\n                if len(trend_slice) < 100 or len(btc4_slice) < 80:\n                    continue\n                regime = engine.analyze_regime_from_candles(btc4_slice, btc1_slice)\n                sig = engine.analyze_symbol_from_candles(symbol, entry[: i + 1], trend_slice, regime, quote_volume, 0.0)\n                setup = str(getattr(sig, "setup", "unknown") or "unknown")\n                if getattr(sig, "entry", 0) <= 0:\n                    diag["reject_reasons"]["NO_RAW_SETUP"] = diag["reject_reasons"].get("NO_RAW_SETUP", 0) + 1\n                    continue\n                diag["raw_setups_total"] += 1\n                diag["setup_counts"][setup] = diag["setup_counts"].get(setup, 0) + 1\n                if allowed_setups and setup not in allowed_setups:\n                    diag["reject_reasons"]["SETUP_NOT_ALLOWED"] = diag["reject_reasons"].get("SETUP_NOT_ALLOWED", 0) + 1\n                    continue\n                diag["after_setup_whitelist"] += 1\n                if setup == "trend" and not env_bool("ENABLE_TREND_SETUP", False):\n                    diag["reject_reasons"]["TREND_DISABLED"] = diag["reject_reasons"].get("TREND_DISABLED", 0) + 1\n                    continue\n                diag["after_trend_disabled"] += 1\n                if setup == "breakout" and not env_bool("ENABLE_BREAKOUT_SETUP", False):\n                    diag["reject_reasons"]["BREAKOUT_DISABLED"] = diag["reject_reasons"].get("BREAKOUT_DISABLED", 0) + 1\n                    continue\n                diag["after_breakout_disabled"] += 1\n                if safe_float(getattr(sig, "atr_pct", 0.0), 0.0) < st.min_atr_pct:\n                    diag["reject_reasons"]["MIN_ATR_FILTERED"] = diag["reject_reasons"].get("MIN_ATR_FILTERED", 0) + 1\n                    continue\n                diag["after_min_atr"] += 1\n                if safe_float(getattr(sig, "score", 0.0), 0.0) < st.score_threshold:\n                    diag["reject_reasons"]["SCORE_TOO_LOW"] = diag["reject_reasons"].get("SCORE_TOO_LOW", 0) + 1\n                    continue\n                if getattr(sig, "direction", "") not in {"LONG", "SHORT"}:\n                    key = "NO_TRADE_BLOCKERS"\n                    for b in list(getattr(sig, "blockers", []) or [])[:3]:\n                        bs = str(b)\n                        if "成本" in bs: key = "COST_FILTER"; break\n                        if "RR" in bs or "R:R" in bs: key = "RR_FILTER"; break\n                        if "ATR" in bs: key = "MIN_ATR_FILTERED"; break\n                        if "评分" in bs: key = "SCORE_TOO_LOW"; break\n                    diag["reject_reasons"][key] = diag["reject_reasons"].get(key, 0) + 1\n                    continue\n                diag["after_score_threshold"] += 1\n                entry_i = i + 1 + max(0, st.entry_delay_bars)\n                if env_bool("ENABLE_CONFIRM_V2", False) and not self._confirm_v2_ok(sig.direction, entry, i, entry_i):\n                    diag["reject_reasons"]["CONFIRM_V2_FAILED"] = diag["reject_reasons"].get("CONFIRM_V2_FAILED", 0) + 1\n                    continue\n                diag["after_confirm_v2"] += 1\n                diag["after_cost_filter"] += 1\n                diag["after_rr_filter"] += 1\n                trade = self._simulate_trade(symbol, sig, entry, entry_i, st)\n                if trade:\n                    trades.append(trade)\n                    diag["final_trades"] += 1\n                    open_until = min(entry_i + trade.bars, len(entry) - 1)\n            getattr(self, "_v3_diag", {})[symbol] = diag\n            return trades\n        except Exception:\n            _v3_logging.exception("BACKTEST_V3_DIAG_SYMBOL_FAILED symbol=%s", symbol)\n            getattr(self, "_v3_diag", {})[symbol] = diag\n            return prev_sym(self, symbol, quote_volume, settings_override)\n\n    def backtest_many(self, symbols, settings_override=None):\n        self._v3_diag = {}\n        trades = []\n        for idx, (sym, qv) in enumerate(symbols, start=1):\n            _v3_logging.info("回测[V3] %s/%s %s", idx, len(symbols), sym)\n            try:\n                trades.extend(self.backtest_symbol(sym, qv, settings_override))\n            except Exception:\n                _v3_logging.error("回测[V3]失败 %s\\n%s", sym, traceback.format_exc())\n        trades.sort(key=lambda t: t.entry_time)\n        try:\n            out = {"time": utc_now().isoformat(), "settings": {\n                "BACKTEST_OFFLINE_ONLY": _v3_bool("BACKTEST_OFFLINE_ONLY", False),\n                "BACKTEST_START": (settings_override or self.settings).backtest_start,\n                "BACKTEST_END": (settings_override or self.settings).backtest_end,\n                "BACKTEST_LIMIT": (settings_override or self.settings).backtest_limit,\n                "SETUP_WHITELIST": env_str("SETUP_WHITELIST", ""),\n                "ENABLE_CONFIRM_V2": env_bool("ENABLE_CONFIRM_V2", False),\n                "MIN_ATR_PCT": (settings_override or self.settings).min_atr_pct,\n                "SCORE_THRESHOLD": (settings_override or self.settings).score_threshold,\n            }, "symbols": getattr(self, "_v3_diag", {})}\n            p = self.settings.workspace / "backtest_filter_diagnostic.json"\n            _atomic_write_json(p, out)\n            lines = ["# Backtest Filter Diagnostic", "", f"time: {out[\'time\']}", ""]\n            for sym, d in out["symbols"].items():\n                lines.append(f"## {sym}")\n                for k in ["raw_market_bars","raw_setups_total","after_setup_whitelist","after_trend_disabled","after_breakout_disabled","after_min_atr","after_score_threshold","after_confirm_v2","after_cost_filter","after_rr_filter","final_trades"]:\n                    lines.append(f"- {k}: {d.get(k,0)}")\n                lines.append(f"- setup_counts: {d.get(\'setup_counts\',{})}")\n                lines.append(f"- reject_reasons: {d.get(\'reject_reasons\',{})}")\n                lines.append("")\n            (self.settings.workspace / "backtest_filter_diagnostic.md").write_text("\\n".join(lines), encoding="utf-8")\n        except Exception:\n            _v3_logging.exception("BACKTEST_V3_DIAG_WRITE_FAILED")\n        return trades\n\n    B.backtest_symbol = backtest_symbol\n    B.backtest_many = backtest_many\n    B._chatgpt_v3_diag = True\n\n\ntry:\n    _v3_patch_exchange_broker_final_guard()\n    _v3_patch_broker_can_open_today()\n    _v3_patch_portfolio_risk()\n    _v3_patch_process_dashboard_and_payload()\n    _v3_patch_health_monitor()\n    _v3_patch_backtest_offline_and_diag()\n    _v3_logging.info("CHATGPT_HOTFIX_V3_LOADED")\nexcept Exception:\n    _v3_logging.exception("CHATGPT_HOTFIX_V3_LOAD_FAILED")\n# === CHATGPT_HOTFIX_V3_END ===\n\'\'\'\n\nDASHBOARD_V3_BLOCK = r"""\n# === CHATGPT_DASHBOARD_HOTFIX_V3_ACTIVE_START ===\n# Active Dashboard V3 overrides. Must appear before HTTPServer. Fixes equity naming, over-max display,\n# held-symbol candidate marking, and clearer scan statistics.\n\ndef _v3_f(v, default=0.0):\n    try:\n        if v in (None, "", "—", "N/A"):\n            return float(default)\n        return float(v)\n    except Exception:\n        return float(default)\n\n\ndef _v3_money(v):\n    try:\n        return fmt_num(v)\n    except Exception:\n        return str(v if v not in (None, "") else "—")\n\n\ndef _v3_pnl_cls(v):\n    f = _v3_f(v, 0.0)\n    return "pos" if f > 0 else "neg" if f < 0 else "muted"\n\n\ndef _v3_prot_badge(status):\n    st = str(status or "NO_PROTECTION").upper()\n    if st == "PROTECTED":\n        return \'<span class="badge badge-green">已保护</span>\'\n    if st in {"STOP_ONLY", "TP_ONLY"}:\n        return \'<span class="badge badge-yellow">部分保护</span>\'\n    return \'<span class="badge badge-red">未保护</span>\'\n\n\ndef build_overview(health, risk, proc, scan_stats=None):\n    broker = ((health or {}).get("broker") or {})\n    config = ((health or {}).get("config") or {})\n    mode = str((health or {}).get("mode") or config.get("trading_mode") or "—").upper()\n    status = str((health or {}).get("status", "—")).upper()\n    positions = broker.get("position_detail", {}) if isinstance(broker.get("position_detail", {}), dict) else {}\n    pos_cnt = int(broker.get("positions", len(positions)) or 0)\n    max_pos = config.get("MAX_POSITIONS", config.get("max_positions", "—"))\n    try:\n        over = pos_cnt > int(max_pos)\n        full = pos_cnt >= int(max_pos)\n    except Exception:\n        over = full = False\n    wallet = _v3_f(broker.get("wallet_balance"), 0.0)\n    unreal = _v3_f(broker.get("total_unrealized_pnl"), 0.0)\n    equity = wallet + unreal if (wallet or unreal) else _v3_f(broker.get("equity"), 0.0)\n    avail = broker.get("available_balance", "—")\n    total_notional = broker.get("total_notional", 0.0)\n    total_im = broker.get("total_initial_margin", 0.0)\n    ss = scan_stats or {}\n    scan_total = ss.get("universe_total", ss.get("pool_size", "—"))\n    scan_allowed = ss.get("allowed", "—")\n    scan_blocked = ss.get("blocked", "—")\n    scan_ui = ss.get("ui_display_top_n", "—")\n    scan_top = ss.get("top_block_reasons", []) or []\n    top_block_str = " | ".join(f"{x.get(\'reason\')}:{x.get(\'count\')}" for x in scan_top[:3]) if isinstance(scan_top, list) else "—"\n    pc = broker.get("position_counts", {}) if isinstance(broker.get("position_counts", {}), dict) else {}\n    by_dir = pc.get("by_direction", pc) if isinstance(pc, dict) else {}\n    by_sector = pc.get("by_sector", pc.get("sector", {})) if isinstance(pc, dict) else {}\n    freeze_text = "OVER_MAX_POSITIONS 新开仓冻结" if over else ("达到上限，新开仓冻结" if full else "正常")\n    freeze_badge = status_badge("ERROR" if over else "WARNING" if full else "OK", freeze_text)\n    return f\'\'\'\n    <div class="overview-grid">\n      <div class="ov-card"><div class="ov-label">机器人状态</div><div class="ov-val">{status_badge(status)}</div></div>\n      <div class="ov-card"><div class="ov-label">运行模式</div><div class="ov-val">{status_badge(mode)}</div></div>\n      <div class="ov-card"><div class="ov-label">钱包余额(不含浮盈亏)</div><div class="ov-val big-num">{esc(_v3_money(wallet))}</div></div>\n      <div class="ov-card"><div class="ov-label">总未实现盈亏</div><div class="ov-val {_v3_pnl_cls(unreal)} big-num">{esc(_v3_money(unreal))}</div></div>\n      <div class="ov-card"><div class="ov-label">总权益=钱包+浮盈亏</div><div class="ov-val {_v3_pnl_cls(equity-wallet)} big-num">{esc(_v3_money(equity))}</div></div>\n      <div class="ov-card"><div class="ov-label">可用余额</div><div class="ov-val big-num">{esc(_v3_money(avail))}</div></div>\n      <div class="ov-card"><div class="ov-label">当前持仓 / 上限</div><div class="ov-val {\'neg\' if over else \'warn\' if full else \'\'} big-num">{esc(pos_cnt)} / {esc(max_pos)}</div></div>\n      <div class="ov-card"><div class="ov-label">新开仓状态</div><div class="ov-val">{freeze_badge}</div></div>\n      <div class="ov-card"><div class="ov-label">LONG / SHORT</div><div class="ov-val">{esc(by_dir.get(\'LONG\',0))} / {esc(by_dir.get(\'SHORT\',0))}</div></div>\n      <div class="ov-card"><div class="ov-label">ALT/板块</div><div class="ov-val small">{esc(by_sector)}</div></div>\n      <div class="ov-card"><div class="ov-label">总名义价值</div><div class="ov-val">{esc(_v3_money(total_notional))} USDT</div></div>\n      <div class="ov-card"><div class="ov-label">已用初始保证金</div><div class="ov-val">{esc(_v3_money(total_im))} USDT</div></div>\n      <div class="ov-card"><div class="ov-label">实际扫描 / UI展示</div><div class="ov-val">{esc(scan_total)} / {esc(scan_ui)}</div></div>\n      <div class="ov-card"><div class="ov-label">通过 / 拦截</div><div class="ov-val">{esc(scan_allowed)} / {esc(scan_blocked)}</div></div>\n      <div class="ov-card ov-wide"><div class="ov-label">主要拦截原因</div><div class="ov-val small">{esc(top_block_str)}</div></div>\n    </div>\'\'\'\n\n\ndef build_positions(health, proc=None):\n    broker_pos = (((health or {}).get("broker") or {}).get("position_detail") or {})\n    if not isinstance(broker_pos, dict) or not broker_pos:\n        return \'<p class="muted" style="padding:12px 0">暂无持仓</p>\'\n    rows = ""\n    for sym, p in broker_pos.items():\n        if not isinstance(p, dict):\n            continue\n        direction = p.get("direction") or p.get("positionSide") or "—"\n        qty = p.get("qty_abs", p.get("positionAmt", "—"))\n        entry = p.get("entryPrice", p.get("entry", "—"))\n        mark = p.get("markPrice", "—")\n        notional = p.get("notional", "—")\n        im = p.get("initial_margin", p.get("positionInitialMargin", "—"))\n        lev = p.get("leverage", "—")\n        mt = str(p.get("marginType", "cross")).lower()\n        pnl = p.get("unRealizedProfit", p.get("unrealizedProfit", "—"))\n        roe = p.get("roe_pct", "—")\n        try: roe_s = f"{float(roe):.2f}%"\n        except Exception: roe_s = "—"\n        liq = p.get("liquidationPrice", "—")\n        if str(liq) in {"", "0", "0.0", "None"}: liq = "N/A"\n        sl = p.get("stop_loss", "—") or "—"\n        tp = p.get("tp2", p.get("take_profit", "—")) or "—"\n        prot = p.get("protection_status", "NO_PROTECTION")\n        ocount = p.get("open_orders_count", 0)\n        rows += f\'\'\'<tr>\n          <td class="sym">{esc(sym)}</td><td>{dir_badge(direction)}</td><td>{esc(fmt_num(qty))}</td>\n          <td>{esc(fmt_num(entry))}</td><td>{esc(fmt_num(mark))}</td>\n          <td>{esc(fmt_num(notional))}</td><td>{esc(fmt_num(im))}</td><td>{esc(fmt_num(lev))}x</td><td>{esc(mt)}</td>\n          <td class="{_v3_pnl_cls(pnl)}">{esc(fmt_num(pnl))}</td><td class="{_v3_pnl_cls(roe)}">{esc(roe_s)}</td><td>{esc(fmt_num(liq))}</td>\n          <td class="neg">{esc(fmt_num(sl))}</td><td class="pos">{esc(fmt_num(tp))}</td><td>{_v3_prot_badge(prot)}</td><td>{esc(ocount)}</td>\n        </tr>\'\'\'\n    return \'<div class="table-wrap"><table><thead><tr><th>币对</th><th>方向</th><th>数量</th><th>开仓价</th><th>最新价</th><th>名义价值</th><th>初始保证金</th><th>杠杆</th><th>模式</th><th>浮盈亏</th><th>ROE%</th><th>强平价</th><th>止损</th><th>止盈</th><th>保护</th><th>挂单</th></tr></thead><tbody>\' + rows + \'</tbody></table></div>\'\n\n\ndef build_signals(proc):\n    top = (proc or {}).get("top", []) if isinstance(proc, dict) else []\n    held = set()\n    try:\n        health = read_json("healthcheck.json") or {}\n        held = set((((health.get("broker") or {}).get("position_detail") or {}).keys()))\n    except Exception:\n        held = set()\n    if not isinstance(top, list) or not top:\n        return \'<p class="muted" style="padding:12px 0">暂无候选信号</p>\'\n    rows = ""\n    for x in top[:30]:\n        if not isinstance(x, dict): continue\n        sym = x.get("symbol", "—")\n        direction = x.get("direction", x.get("decision", "NO_TRADE"))\n        risk_blockers = list(x.get("risk_blockers", []) or [])\n        blocker = x.get("execution_block_reason") or x.get("blocker") or x.get("block_reason") or ""\n        if sym in held:\n            blocker = "已有持仓，被拦截"\n            direction = "NO_TRADE"\n        if not blocker and risk_blockers:\n            blocker = " | ".join(str(b) for b in risk_blockers[:2])\n        status = "可交易" if str(direction).upper() in {"LONG","SHORT","TRADE"} and not blocker else "被拦截"\n        rows += f\'\'\'<tr><td class="sym">{esc(sym)}</td><td>{esc(x.get(\'process_tier\', x.get(\'tier\',\'—\')))}</td><td>{esc(fmt_num(x.get(\'score\',\'—\')))}</td><td>{dir_badge(direction)}</td><td>{esc(fmt_num(x.get(\'entry\',\'—\')))}</td><td class="neg">{esc(blocker)}</td><td>{status_badge(\'READY\' if status==\'可交易\' else \'BLOCKED\', status)}</td></tr>\'\'\'\n    return \'<div class="table-wrap"><table><thead><tr><th>币对</th><th>等级</th><th>分数</th><th>方向</th><th>入场价</th><th>拦截原因</th><th>状态</th></tr></thead><tbody>\' + rows + \'</tbody></table></div>\'\n# === CHATGPT_DASHBOARD_HOTFIX_V3_ACTIVE_END ===\n"""\n\nBT_DIAG_SCRIPT = r\'\'\'#!/usr/bin/env python3\n"""Summarize backtest filter diagnostics produced by ChatGPT V3 hotfix."""\nfrom __future__ import annotations\nimport json, sys\nfrom pathlib import Path\nroots = [Path(\'/root/brain/backtest_full_ws\'), Path(\'/root/brain/backtest_bt2_ws\')]\nfor root in roots:\n    p = root / \'backtest_filter_diagnostic.json\'\n    print(\'\\n===\', root, \'===\')\n    if not p.exists():\n        print(\'no diagnostic file:\', p)\n        continue\n    d = json.loads(p.read_text())\n    totals = {}\n    for sym, row in d.get(\'symbols\', {}).items():\n        for k, v in row.items():\n            if isinstance(v, (int, float)):\n                totals[k] = totals.get(k, 0) + v\n    print(json.dumps(totals, ensure_ascii=False, indent=2))\n    # top reject reasons\n    rr = {}\n    for row in d.get(\'symbols\', {}).values():\n        for k, v in (row.get(\'reject_reasons\') or {}).items():\n            rr[k] = rr.get(k, 0) + v\n    print(\'reject_reasons:\', json.dumps(dict(sorted(rr.items(), key=lambda kv: -kv[1])[:20]), ensure_ascii=False, indent=2))\n\'\'\'\n\n\ndef patch_brain():\n    p = ROOT / "brain_v11_1_aipro.py"\n    backup(p)\n    text = p.read_text(encoding="utf-8", errors="ignore")\n    text = replace_block(text, "# === CHATGPT_HOTFIX_V3_START ===", "# === CHATGPT_HOTFIX_V3_END ===", BRAIN_V3_BLOCK, \'if __name__ == "__main__":\')\n    p.write_text(text, encoding="utf-8")\n\n\ndef patch_dashboard():\n    p = ROOT / "dashboard.py"\n    backup(p)\n    text = p.read_text(encoding="utf-8", errors="ignore")\n    marker = \'print(f"Dashboard running on http://{HOST}:{PORT}, data={DATA_DIR}")\'\n    text = replace_block(text, "# === CHATGPT_DASHBOARD_HOTFIX_V3_ACTIVE_START ===", "# === CHATGPT_DASHBOARD_HOTFIX_V3_ACTIVE_END ===", DASHBOARD_V3_BLOCK, marker)\n    p.write_text(text, encoding="utf-8")\n\n\ndef patch_env_and_scripts():\n    env_values = {\n        "MAX_POSITIONS": "5",\n        "MAX_NEW_ENTRIES_PER_CYCLE": "2",\n        "MAX_SAME_DIRECTION_POSITIONS": "5",\n        "MAX_LONG_POSITIONS": "5",\n        "MAX_SHORT_POSITIONS": "5",\n        "MAX_SAME_SECTOR_POSITIONS": "5",\n        "MAX_ALT_POSITIONS": "5",\n        "MAX_SECTOR_POSITIONS": "5",\n        "MAX_POSITIONS_PER_SECTOR": "5",\n        "FREEZE_NEW_ENTRIES_IF_OVER_MAX": "1",\n        "BACKTEST_OFFLINE_ONLY": "1",\n        "NO_API_FALLBACK": "1",\n        "PREFER_LOCAL_KLINES": "1",\n        "LOCAL_KLINE_DIR": "/root/brain/binance_history",\n        "BACKTEST_START": "2023-01-01",\n        "BACKTEST_END": "2026-03-31",\n        "BACKTEST_LIMIT": "120000",\n        "REQUEST_TIMEOUT": "10",\n        "EXCHANGE_INFO_CACHE": "/root/brain/exchange_info_cache.json",\n    }\n    envp = ROOT / ".demo.env"\n    backup(envp)\n    upsert_env(envp, env_values)\n\n    for name in ("run_bt_fixed1.sh", "run_bt_fixed2.sh"):\n        p = ROOT / name\n        if not p.exists():\n            continue\n        backup(p)\n        s = p.read_text(encoding="utf-8", errors="ignore")\n        s = re.sub(r"BACKTEST_END=\\d{4}-\\d{2}-\\d{2}", "BACKTEST_END=2026-03-31", s)\n        s = re.sub(r"BACKTEST_LIMIT=\\d+", "BACKTEST_LIMIT=120000", s)\n        if "BACKTEST_OFFLINE_ONLY=" not in s:\n            s = s.replace("PREFER_LOCAL_KLINES=1 \\\\", "PREFER_LOCAL_KLINES=1 \\\\\\n    BACKTEST_OFFLINE_ONLY=1 \\\\\\n    NO_API_FALLBACK=1 \\\\")\n        p.write_text(s, encoding="utf-8")\n        os.chmod(p, 0o755)\n\n    diag = ROOT / "bt_filter_diagnostic_summary.py"\n    diag.write_text(BT_DIAG_SCRIPT, encoding="utf-8")\n    os.chmod(diag, 0o755)\n\n\ndef main():\n    if not ROOT.exists():\n        raise SystemExit(f"BRAIN_ROOT not found: {ROOT}")\n    patch_brain()\n    patch_dashboard()\n    patch_env_and_scripts()\n    print("CHATGPT_HOTFIX_V3_APPLIED")\n    print("Modified: brain_v11_1_aipro.py, dashboard.py, .demo.env, run_bt_fixed1.sh, run_bt_fixed2.sh")\n    print("Added: bt_filter_diagnostic_summary.py")\n    print("Next: python3 -m py_compile brain_v11_1_aipro.py dashboard.py bt_analyze.py")\n\n\nif __name__ == "__main__":\n    main()\n'
V4_CODE = '#!/usr/bin/env python3\n"""\nChatGPT Hotfix V4 for Brain V11\nFixes missing exchange close history / realized PnL / balance columns in Dashboard.\n\nSafe behavior:\n- Does not cancel orders, does not close positions, does not change strategy params.\n- Best-effort: if trade-history API fails, bot continues normally and logs warning.\n"""\nfrom __future__ import annotations\nimport os, re, shutil, datetime\nfrom pathlib import Path\n\nROOT = Path(os.environ.get("BRAIN_ROOT", "/root/brain")).resolve()\nTS = datetime.datetime.utcnow().strftime("%Y%m%d_%H%M%S")\n\n\ndef backup(path: Path) -> None:\n    if path.exists():\n        shutil.copy2(path, path.with_suffix(path.suffix + f".bak_hotfix_v4_{TS}"))\n\n\ndef replace_block(text: str, start: str, end: str, block: str, insert_before: str) -> str:\n    pat = re.compile(re.escape(start) + r".*?" + re.escape(end) + r"\\n?", re.S)\n    text = pat.sub("", text)\n    idx = text.rfind(insert_before)\n    if idx < 0:\n        raise SystemExit(f"Cannot find insert marker: {insert_before!r}")\n    return text[:idx] + block.rstrip() + "\\n\\n" + text[idx:]\n\n\nBRAIN_V4_BLOCK = r\'\'\'\n# === CHATGPT_HOTFIX_V4_TRADE_HISTORY_START ===\n# Hotfix V4: sync exchange fills/closed-position history so Dashboard can show realized PnL and balance/equity.\n# This is read-only except appending deduped close rows to trades.csv and writing exchange_trade_history.json.\ntry:\n    import csv as _v4_csv, json as _v4_json, logging as _v4_logging, os as _v4_os, time as _v4_time\n    from pathlib import Path as _v4_Path\nexcept Exception:\n    pass\n\n\ndef _v4_float(v, default=0.0):\n    try:\n        if v in (None, "", "—", "N/A"):\n            return float(default)\n        return float(v)\n    except Exception:\n        return float(default)\n\n\ndef _v4_bool(name, default=True):\n    return str(_v4_os.environ.get(name, "1" if default else "0")).strip().lower() in {"1", "true", "yes", "y", "on"}\n\n\ndef _v4_ms_to_iso(ms):\n    try:\n        return ms_to_iso(int(ms))\n    except Exception:\n        try:\n            return dt.datetime.fromtimestamp(int(ms)/1000, tz=UTC).isoformat()\n        except Exception:\n            return utc_now().isoformat()\n\n\ndef _v4_read_json(path, default):\n    try:\n        p = _v4_Path(path)\n        if p.exists():\n            return _v4_json.loads(p.read_text(encoding="utf-8", errors="ignore"))\n    except Exception:\n        pass\n    return default\n\n\ndef _v4_write_json(path, obj):\n    try:\n        _atomic_write_json(_v4_Path(path), obj)\n    except Exception:\n        _v4_Path(path).write_text(_v4_json.dumps(obj, ensure_ascii=False, indent=2), encoding="utf-8")\n\n\ndef _v4_event_id(symbol, row):\n    for k in ("id", "tradeId", "a"):\n        if row.get(k) not in (None, ""):\n            return f"trade:{symbol}:{row.get(k)}"\n    return f"trade:{symbol}:{row.get(\'orderId\',\'\')}:{row.get(\'time\',\'\')}:{row.get(\'qty\',\'\')}:{row.get(\'price\',\'\')}"\n\n\ndef _v4_infer_direction(side, position_side, realized):\n    ps = str(position_side or "").upper()\n    if ps in {"LONG", "SHORT"}:\n        return ps\n    s = str(side or "").upper()\n    # For close fills: SELL closes LONG, BUY closes SHORT. For open fills: BUY opens LONG, SELL opens SHORT.\n    if abs(_v4_float(realized, 0.0)) > 1e-12:\n        return "LONG" if s == "SELL" else "SHORT" if s == "BUY" else "—"\n    return "LONG" if s == "BUY" else "SHORT" if s == "SELL" else "—"\n\n\ndef _v4_patch_client_trade_history():\n    C = globals().get("BinanceFuturesClientV9") or globals().get("BinanceFuturesClient")\n    if not C or getattr(C, "_chatgpt_v4_trade_history", False):\n        return\n\n    def user_trades(self, symbol, limit=50, start_ms=None, end_ms=None):\n        params = {"symbol": symbol, "limit": max(1, min(int(limit or 50), 1000))}\n        if start_ms:\n            params["startTime"] = int(start_ms)\n        if end_ms:\n            params["endTime"] = int(end_ms)\n        data = self.signed("GET", "/fapi/v1/userTrades", params)\n        return data if isinstance(data, list) else []\n\n    def income_history(self, symbol=None, income_type=None, limit=100, start_ms=None, end_ms=None):\n        params = {"limit": max(1, min(int(limit or 100), 1000))}\n        if symbol:\n            params["symbol"] = symbol\n        if income_type:\n            params["incomeType"] = income_type\n        if start_ms:\n            params["startTime"] = int(start_ms)\n        if end_ms:\n            params["endTime"] = int(end_ms)\n        data = self.signed("GET", "/fapi/v1/income", params)\n        return data if isinstance(data, list) else []\n\n    C.user_trades = user_trades\n    C.income_history = income_history\n    C._chatgpt_v4_trade_history = True\n\n\ndef _v4_journal_symbols(journal_file, max_rows=800):\n    symbols = set()\n    try:\n        p = _v4_Path(journal_file)\n        if p.exists():\n            with p.open("r", encoding="utf-8", newline="") as f:\n                rows = list(_v4_csv.DictReader(f))[-max_rows:]\n            for r in rows:\n                s = str(r.get("symbol", "")).strip().upper()\n                if s.endswith("USDT"):\n                    symbols.add(s)\n    except Exception:\n        pass\n    return symbols\n\n\ndef _v4_known_symbols_from_workspace(ws):\n    symbols = set()\n    for name in ("process_dashboard.json", "scan_stats.json", "ai_candidates.json"):\n        try:\n            obj = _v4_read_json(_v4_Path(ws) / name, {})\n            pools = []\n            if isinstance(obj, dict):\n                for k in ("top", "candidates", "signals", "recent_trades"):\n                    if isinstance(obj.get(k), list):\n                        pools.extend(obj.get(k))\n            for r in pools:\n                if isinstance(r, dict):\n                    s = str(r.get("symbol", "")).strip().upper()\n                    if s.endswith("USDT"):\n                        symbols.add(s)\n        except Exception:\n            pass\n    return symbols\n\n\ndef _v4_patch_broker_trade_sync():\n    B = globals().get("ExchangeBrokerV6") or globals().get("ExchangeBroker")\n    if not B or getattr(B, "_chatgpt_v4_trade_sync", False):\n        return\n\n    def sync_exchange_trade_history(self, limit_per_symbol=None):\n        if not _v4_bool("SYNC_EXCHANGE_TRADE_HISTORY", True):\n            return {"events": [], "closed": [], "disabled": True}\n        ws = _v4_Path(getattr(self.settings, "workspace", "/root/brain/brain_demo_data"))\n        ws.mkdir(parents=True, exist_ok=True)\n        hist_path = ws / "exchange_trade_history.json"\n        state_path = ws / "exchange_trade_history_state.json"\n        income_path = ws / "exchange_income_history.json"\n        limit_per_symbol = int(limit_per_symbol or _v4_os.environ.get("TRADE_HISTORY_LIMIT_PER_SYMBOL", "80"))\n\n        old = _v4_read_json(hist_path, {"events": [], "closed": []})\n        old_events = old.get("events", []) if isinstance(old, dict) else []\n        state = _v4_read_json(state_path, {"journaled_event_ids": []})\n        journaled = set(state.get("journaled_event_ids", []) if isinstance(state, dict) else [])\n        existing = set()\n        merged = []\n        for e in old_events:\n            if isinstance(e, dict):\n                eid = str(e.get("event_id", ""))\n                if eid and eid not in existing:\n                    existing.add(eid)\n                    merged.append(e)\n\n        symbols = set()\n        try:\n            positions = self.positions()\n            symbols.update(str(s).upper() for s in (positions or {}).keys() if str(s).upper().endswith("USDT"))\n        except Exception:\n            positions = {}\n        symbols.update(_v4_journal_symbols(getattr(self.settings, "journal_file", "")))\n        symbols.update(_v4_known_symbols_from_workspace(ws))\n        # Cap symbol count to avoid rate-limit. Current/previously traded symbols are enough for history display.\n        symbols = sorted(symbols)[:120]\n\n        bal = {}\n        try:\n            bal = self.account_detail() if hasattr(self, "account_detail") else {}\n        except Exception:\n            bal = {}\n        wallet = _v4_float(bal.get("wallet_balance"), 0.0)\n        unreal = _v4_float(bal.get("total_unrealized_pnl"), 0.0)\n        equity = _v4_float(bal.get("equity"), wallet + unreal)\n        avail = _v4_float(bal.get("available_balance"), 0.0)\n\n        new_close_count = 0\n        api_errors = []\n        for sym in symbols:\n            try:\n                rows = self.client.user_trades(sym, limit=limit_per_symbol)\n            except Exception as exc:\n                api_errors.append(f"{sym}: {exc}")\n                continue\n            for r in rows or []:\n                if not isinstance(r, dict):\n                    continue\n                eid = _v4_event_id(sym, r)\n                if eid in existing:\n                    continue\n                realized = _v4_float(r.get("realizedPnl", r.get("realizedProfit", 0.0)), 0.0)\n                commission = _v4_float(r.get("commission"), 0.0)\n                side = str(r.get("side", "")).upper()\n                direction = _v4_infer_direction(side, r.get("positionSide"), realized)\n                event = "EXCHANGE_CLOSE" if abs(realized) > 1e-12 else "EXCHANGE_FILL"\n                qty = _v4_float(r.get("qty", r.get("quantity", 0.0)), 0.0)\n                price = _v4_float(r.get("price"), 0.0)\n                quote_qty = _v4_float(r.get("quoteQty", qty * price), qty * price)\n                item = {\n                    "event_id": eid,\n                    "time": _v4_ms_to_iso(r.get("time", int(_v4_time.time()*1000))),\n                    "event": event,\n                    "fill_type": "CLOSE" if event == "EXCHANGE_CLOSE" else "OPEN_OR_ADD",\n                    "symbol": sym,\n                    "direction": direction,\n                    "side": side,\n                    "price": price,\n                    "qty": qty,\n                    "quote_qty": quote_qty,\n                    "pnl": realized,\n                    "realized_pnl": realized,\n                    "commission": commission,\n                    "commission_asset": r.get("commissionAsset", "USDT"),\n                    "balance": wallet,\n                    "wallet_balance": wallet,\n                    "equity": equity,\n                    "available_balance": avail,\n                    "order_id": r.get("orderId", ""),\n                    "trade_id": r.get("id", r.get("tradeId", "")),\n                    "source": "userTrades",\n                }\n                merged.append(item)\n                existing.add(eid)\n                if event == "EXCHANGE_CLOSE" and eid not in journaled:\n                    try:\n                        self.journal.write({\n                            "time": item["time"], "event": "EXCHANGE_CLOSE", "symbol": sym, "direction": direction,\n                            "setup": "exchange", "qty": qty, "price": price, "entry": "", "stop_loss": "", "tp1": "", "tp2": "",\n                            "score": "", "risk_usdt": "", "pnl": realized, "balance": wallet, "equity": equity,\n                            "available_balance": avail, "commission": commission, "order_id": item["order_id"],\n                            "trade_id": item["trade_id"], "reason": "exchange userTrades realizedPnl sync",\n                        })\n                        journaled.add(eid)\n                        new_close_count += 1\n                    except Exception:\n                        _v4_logging.exception("V4_JOURNAL_EXCHANGE_CLOSE_WRITE_FAILED symbol=%s eid=%s", sym, eid)\n\n        income_rows = []\n        try:\n            income_rows = self.client.income_history(income_type="REALIZED_PNL", limit=100)\n        except Exception as exc:\n            api_errors.append(f"income: {exc}")\n        income_events = []\n        for r in income_rows or []:\n            if not isinstance(r, dict):\n                continue\n            sym = str(r.get("symbol", "")).upper()\n            pnl = _v4_float(r.get("income"), 0.0)\n            if not sym or abs(pnl) <= 1e-12:\n                continue\n            income_events.append({\n                "event_id": f"income:{sym}:{r.get(\'tranId\', \'\')}:{r.get(\'time\',\'\')}",\n                "time": _v4_ms_to_iso(r.get("time", int(_v4_time.time()*1000))),\n                "event": "REALIZED_PNL_INCOME",\n                "symbol": sym,\n                "pnl": pnl,\n                "realized_pnl": pnl,\n                "income_type": r.get("incomeType", "REALIZED_PNL"),\n                "balance": wallet,\n                "equity": equity,\n                "available_balance": avail,\n                "source": "income",\n            })\n\n        def _sort_key(x):\n            return str((x or {}).get("time", ""))\n        merged = sorted([x for x in merged if isinstance(x, dict)], key=_sort_key)[-500:]\n        closed = [x for x in merged if str(x.get("event", "")).upper() in {"EXCHANGE_CLOSE", "STOP", "TP1", "TP2", "CLOSED_NO_PROTECTION"} or abs(_v4_float(x.get("pnl"), 0.0)) > 1e-12]\n        obj = {\n            "time": utc_now().isoformat(),\n            "symbols_checked": symbols,\n            "events": merged,\n            "closed": closed[-300:],\n            "new_close_rows_appended": new_close_count,\n            "wallet_balance": wallet,\n            "equity": equity,\n            "available_balance": avail,\n            "api_errors": api_errors[-20:],\n        }\n        _v4_write_json(hist_path, obj)\n        _v4_write_json(income_path, {"time": utc_now().isoformat(), "events": income_events[-300:], "api_errors": api_errors[-20:]})\n        _v4_write_json(state_path, {"time": utc_now().isoformat(), "journaled_event_ids": sorted(journaled)[-2000:]})\n        if api_errors:\n            _v4_logging.warning("V4_EXCHANGE_TRADE_HISTORY_API_ERRORS %s", api_errors[-5:])\n        return obj\n\n    B.sync_exchange_trade_history = sync_exchange_trade_history\n    B._chatgpt_v4_trade_sync = True\n\n\ndef _v4_patch_health_trade_history():\n    H = globals().get("HealthMonitor")\n    if not H or getattr(H, "_chatgpt_v4_trade_history", False):\n        return\n    prev = getattr(H, "snapshot", None)\n    if not prev:\n        return\n\n    def snapshot(self, include_api=True):\n        obj = prev(self, include_api)\n        try:\n            if hasattr(self.broker, "sync_exchange_trade_history") and self.settings.trading_mode in {"demo", "live"}:\n                hist = self.broker.sync_exchange_trade_history()\n                broker = obj.setdefault("broker", {})\n                events = hist.get("events", []) if isinstance(hist, dict) else []\n                closed = hist.get("closed", []) if isinstance(hist, dict) else []\n                broker["recent_trades"] = list(reversed(events[-30:]))\n                broker["closed_trades"] = list(reversed(closed[-30:]))\n                broker["trade_history_last_sync"] = hist.get("time") if isinstance(hist, dict) else utc_now().isoformat()\n                broker["trade_history_api_errors"] = hist.get("api_errors", []) if isinstance(hist, dict) else []\n                _atomic_write_json(self.path, obj)\n        except Exception:\n            _v4_logging.exception("CHATGPT_V4_HEALTH_TRADE_HISTORY_SYNC_FAILED")\n        return obj\n\n    H.snapshot = snapshot\n    H._chatgpt_v4_trade_history = True\n\n\ntry:\n    _v4_patch_client_trade_history()\n    _v4_patch_broker_trade_sync()\n    _v4_patch_health_trade_history()\n    _v4_logging.info("CHATGPT_HOTFIX_V4_TRADE_HISTORY_LOADED")\nexcept Exception:\n    _v4_logging.exception("CHATGPT_HOTFIX_V4_TRADE_HISTORY_LOAD_FAILED")\n# === CHATGPT_HOTFIX_V4_TRADE_HISTORY_END ===\n\'\'\'\n\nDASHBOARD_V4_BLOCK = r"""\n# === CHATGPT_DASHBOARD_HOTFIX_V4_HISTORY_START ===\n# Dashboard V4: recent exchange fills + closed-position history with realized PnL/balance/equity.\n\ndef _v4_load_json_file(name, default=None):\n    try:\n        p = DATA_DIR / name\n        if p.exists():\n            return json.loads(p.read_text(encoding="utf-8", errors="ignore"))\n    except Exception:\n        pass\n    return {} if default is None else default\n\n\ndef _v4_f(v, default=0.0):\n    try:\n        if v in (None, "", "—", "N/A"):\n            return float(default)\n        return float(v)\n    except Exception:\n        return float(default)\n\n\ndef _v4_time_key(x):\n    return str((x or {}).get("time", ""))\n\n\ndef _v4_norm_event(r, source="journal"):\n    if not isinstance(r, dict):\n        return {}\n    event = str(r.get("event", r.get("type", "—"))).upper()\n    pnl = r.get("pnl", r.get("realized_pnl", r.get("realizedPnl", "")))\n    bal = r.get("balance", r.get("wallet_balance", ""))\n    equity = r.get("equity", r.get("margin_balance", ""))\n    return {\n        "time": r.get("time", "—"),\n        "event": event,\n        "symbol": r.get("symbol", "—"),\n        "direction": r.get("direction", r.get("side", "—")),\n        "setup": r.get("setup", r.get("fill_type", "—")),\n        "price": r.get("price", r.get("entry", r.get("exit", "—"))),\n        "qty": r.get("qty", r.get("quantity", "—")),\n        "pnl": pnl,\n        "commission": r.get("commission", "—"),\n        "balance": bal,\n        "equity": equity,\n        "available_balance": r.get("available_balance", ""),\n        "order_id": r.get("order_id", r.get("orderId", "")),\n        "trade_id": r.get("trade_id", r.get("tradeId", "")),\n        "reason": r.get("reason", r.get("source", source)),\n        "source": source,\n    }\n\n\ndef _v4_combined_trade_rows(journal_rows=None):\n    out = []\n    seen = set()\n    hist = _v4_load_json_file("exchange_trade_history.json", {})\n    for r in (hist.get("events", []) if isinstance(hist, dict) else []):\n        nr = _v4_norm_event(r, "exchange")\n        key = (nr.get("time"), nr.get("event"), nr.get("symbol"), nr.get("order_id"), nr.get("trade_id"), nr.get("qty"), nr.get("price"))\n        if key not in seen:\n            seen.add(key); out.append(nr)\n    for r in journal_rows or []:\n        nr = _v4_norm_event(r, "journal")\n        key = (nr.get("time"), nr.get("event"), nr.get("symbol"), nr.get("order_id"), nr.get("trade_id"), nr.get("qty"), nr.get("price"))\n        if key not in seen:\n            seen.add(key); out.append(nr)\n    return sorted(out, key=_v4_time_key, reverse=True)\n\n\ndef _v4_event_badge(event):\n    e = str(event or "—").upper()\n    if "CLOSE" in e or e in {"STOP", "TP1", "TP2", "REALIZED_PNL_INCOME", "CLOSED_NO_PROTECTION"}:\n        return \'<span class="badge badge-yellow">平仓/结算</span>\'\n    if "OPEN" in e:\n        return \'<span class="badge badge-green">开仓</span>\'\n    if "FILL" in e:\n        return \'<span class="badge badge-blue">成交</span>\'\n    return status_badge(e)\n\n\ndef build_trades(trades):\n    rows_data = _v4_combined_trade_rows(trades)[:40]\n    if not rows_data:\n        return \'<p class="muted" style="padding:12px 0">暂无成交记录</p>\'\n    rows = ""\n    for r in rows_data:\n        pnl = r.get("pnl", "")\n        pnl_cls = pnl_class(pnl) if str(pnl) not in {"", "—"} else "muted"\n        bal = r.get("balance", "")\n        eq = r.get("equity", "")\n        bal_eq = "—"\n        if str(bal) not in {"", "—"} or str(eq) not in {"", "—"}:\n            bal_eq = f"钱包 {fmt_num(bal)} / 权益 {fmt_num(eq)}"\n        pnl_display = pnl if str(pnl) not in {"", "—"} else "—"\n        rows += f\'\'\'<tr>\n          <td>{esc(r.get(\'time\',\'—\'))}</td><td>{_v4_event_badge(r.get(\'event\',\'—\'))}</td><td class="sym">{esc(r.get(\'symbol\',\'—\'))}</td>\n          <td>{dir_badge(r.get(\'direction\',\'—\'))}</td><td>{esc(r.get(\'setup\',\'—\'))}</td>\n          <td>{esc(fmt_num(r.get(\'price\',\'—\')))}</td><td>{esc(fmt_num(r.get(\'qty\',\'—\')))}</td>\n          <td class="{pnl_cls}">{esc(fmt_num(pnl_display))}</td>\n          <td>{esc(fmt_num(r.get(\'commission\',\'—\')))}</td><td>{esc(bal_eq)}</td>\n          <td class="muted small">{esc(r.get(\'reason\',\'\'))}</td>\n        </tr>\'\'\'\n    return \'<div class="table-wrap"><table><thead><tr><th>时间</th><th>事件</th><th>币对</th><th>方向</th><th>策略/类型</th><th>价格</th><th>数量</th><th>已实现盈亏</th><th>手续费</th><th>钱包/权益</th><th>来源/原因</th></tr></thead><tbody>\' + rows + \'</tbody></table></div>\'\n\n\ndef build_position_history(health=None, proc=None, trades=None):\n    hist = _v4_load_json_file("exchange_trade_history.json", {})\n    closed = []\n    if isinstance(hist, dict):\n        closed.extend(hist.get("closed", []) or [])\n    for r in trades or []:\n        ev = str((r or {}).get("event", "")).upper()\n        if ev in {"STOP", "TP1", "TP2", "EXCHANGE_CLOSE", "CLOSED_NO_PROTECTION"}:\n            closed.append(r)\n    rows_data = sorted([_v4_norm_event(r, "history") for r in closed if isinstance(r, dict)], key=_v4_time_key, reverse=True)[:40]\n    if not rows_data:\n        err = ""\n        if isinstance(hist, dict) and hist.get("api_errors"):\n            err = \'<div class="muted small">交易历史同步 API 提示：\' + esc(" | ".join(str(x) for x in hist.get("api_errors", [])[:3])) + \'</div>\'\n        return \'<p class="muted" style="padding:12px 0">暂无已平仓历史/已实现盈亏记录。等 SL/TP/平仓成交后这里会显示。</p>\' + err\n    rows = ""\n    total_pnl = 0.0\n    for r in rows_data:\n        pnl = r.get("pnl", "")\n        total_pnl += _v4_f(pnl, 0.0)\n        pnl_cls = pnl_class(pnl) if str(pnl) not in {"", "—"} else "muted"\n        pnl_display = pnl if str(pnl) not in {"", "—"} else "—"\n        rows += f\'\'\'<tr>\n          <td>{esc(r.get(\'time\',\'—\'))}</td><td class="sym">{esc(r.get(\'symbol\',\'—\'))}</td><td>{dir_badge(r.get(\'direction\',\'—\'))}</td>\n          <td>{esc(fmt_num(r.get(\'price\',\'—\')))}</td><td>{esc(fmt_num(r.get(\'qty\',\'—\')))}</td>\n          <td class="{pnl_cls}">{esc(fmt_num(pnl_display))}</td>\n          <td>{esc(fmt_num(r.get(\'commission\',\'—\')))}</td><td>{esc(fmt_num(r.get(\'balance\',\'—\')))}</td><td>{esc(fmt_num(r.get(\'equity\',\'—\')))}</td>\n          <td class="muted small">{esc(r.get(\'order_id\',\'\'))}</td>\n        </tr>\'\'\'\n    summary = f\'<div class="muted small" style="padding:4px 0 10px">最近 {len(rows_data)} 条平仓/结算记录，合计已实现盈亏：<span class="{pnl_class(total_pnl)}">{esc(fmt_num(total_pnl))} USDT</span></div>\'\n    return summary + \'<div class="table-wrap"><table><thead><tr><th>时间</th><th>币对</th><th>方向</th><th>平仓/成交价</th><th>数量</th><th>已实现盈亏</th><th>手续费</th><th>钱包余额</th><th>总权益</th><th>订单ID</th></tr></thead><tbody>\' + rows + \'</tbody></table></div>\'\n# === CHATGPT_DASHBOARD_HOTFIX_V4_HISTORY_END ===\n"""\n\n\ndef patch_brain():\n    p = ROOT / "brain_v11_1_aipro.py"\n    backup(p)\n    text = p.read_text(encoding="utf-8", errors="ignore")\n    text = replace_block(text, "# === CHATGPT_HOTFIX_V4_TRADE_HISTORY_START ===", "# === CHATGPT_HOTFIX_V4_TRADE_HISTORY_END ===", BRAIN_V4_BLOCK, \'if __name__ == "__main__":\')\n    p.write_text(text, encoding="utf-8")\n\n\ndef patch_dashboard():\n    p = ROOT / "dashboard.py"\n    backup(p)\n    text = p.read_text(encoding="utf-8", errors="ignore")\n    marker = \'print(f"Dashboard running on http://{HOST}:{PORT}, data={DATA_DIR}")\'\n    text = replace_block(text, "# === CHATGPT_DASHBOARD_HOTFIX_V4_HISTORY_START ===", "# === CHATGPT_DASHBOARD_HOTFIX_V4_HISTORY_END ===", DASHBOARD_V4_BLOCK, marker)\n    if "持仓历史 / 平仓盈亏" not in text:\n        insert = """\n\n<!-- ── Position History ── -->\n<div class="section">\n  <div class="section-title">📚 持仓历史 / 平仓盈亏</div>\n  <div class="card card-sm">\n    {build_position_history(health, proc, trades)}\n  </div>\n</div>\n\n"""\n        text = text.replace("\\n<!-- ── Risk ── -->", insert + "\\n<!-- ── Risk ── -->")\n    p.write_text(text, encoding="utf-8")\n\n\ndef patch_env():\n    envp = ROOT / ".demo.env"\n    if not envp.exists():\n        return\n    backup(envp)\n    lines = envp.read_text(encoding="utf-8", errors="ignore").splitlines()\n    keys = {"SYNC_EXCHANGE_TRADE_HISTORY", "TRADE_HISTORY_LIMIT_PER_SYMBOL"}\n    new = []\n    for line in lines:\n        m = re.match(r"(?:export\\s+)?([A-Za-z_][A-Za-z0-9_]*)=", line.strip())\n        if m and m.group(1) in keys:\n            continue\n        new.append(line)\n    new.extend(["", "# === ChatGPT Hotfix V4 trade/history dashboard ===", "export SYNC_EXCHANGE_TRADE_HISTORY=1", "export TRADE_HISTORY_LIMIT_PER_SYMBOL=80"])\n    envp.write_text("\\n".join(new).rstrip()+"\\n", encoding="utf-8")\n\n\ndef main():\n    if not ROOT.exists():\n        raise SystemExit(f"BRAIN_ROOT not found: {ROOT}")\n    patch_brain()\n    patch_dashboard()\n    patch_env()\n    print("CHATGPT_HOTFIX_V4_HISTORY_APPLIED")\n    print("Modified: brain_v11_1_aipro.py, dashboard.py, .demo.env")\n    print("Next: python3 -m py_compile brain_v11_1_aipro.py dashboard.py bt_analyze.py")\n\n\nif __name__ == "__main__":\n    main()\n'


def _run_embedded(label: str, code: str) -> None:
    print(f"\n========== APPLY {label} ==========")
    ns = {"__name__": "__main__", "__file__": f"<{label}_embedded>"}
    try:
        exec(compile(code, f"<{label}_embedded>", "exec"), ns, ns)
    except SystemExit as e:
        # Treat SystemExit(0/None) as success, nonzero as failure.
        code_val = e.code
        if code_val not in (None, 0):
            raise
    print(f"========== {label} DONE ==========\n")


def main() -> int:
    root = os.environ.get("BRAIN_ROOT", "/root/brain")
    print("CHATGPT_HOTFIX_V5_MERGED_START")
    print("BRAIN_ROOT=", root)
    if not os.path.isdir(root):
        print(f"ERROR: BRAIN_ROOT not found: {root}", file=sys.stderr)
        return 2
    # Make sure embedded scripts use the same root.
    os.environ["BRAIN_ROOT"] = root
    try:
        _run_embedded("V3_GUARD_UI_BACKTEST", V3_CODE)
        _run_embedded("V4_TRADE_HISTORY_DASHBOARD", V4_CODE)
    except Exception:
        print("CHATGPT_HOTFIX_V5_MERGED_FAILED", file=sys.stderr)
        traceback.print_exc()
        return 1
    print("CHATGPT_HOTFIX_V5_MERGED_APPLIED")
    print("Modified by V3+V4: brain_v11_1_aipro.py, dashboard.py, .demo.env, run_bt_fixed1.sh, run_bt_fixed2.sh")
    print("Added/updated: bt_filter_diagnostic_summary.py")
    print("Next validation:")
    print("  python3 -m py_compile brain_v11_1_aipro.py dashboard.py bt_analyze.py")
    print("  source .demo.env && python3 brain_v11_1_aipro.py --show-config")
    print("  source .demo.env && python3 brain_v11_1_aipro.py --healthcheck")
    print("  source .demo.env && python3 brain_v11_1_aipro.py --scan")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
